CREATE TABLE users.user_account (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, role VARCHAR(20) NOT NULL CHECK(role='USER'), display_name VARCHAR(100) NOT NULL, email VARCHAR(320), profile_image TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE users.oauth_identity (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES users.user_account(id), provider VARCHAR(20) NOT NULL CHECK(provider IN ('GOOGLE','KAKAO','NAVER')), provider_subject VARCHAR(255) NOT NULL CHECK(btrim(provider_subject)<>''), created_at TIMESTAMPTZ NOT NULL, last_login_at TIMESTAMPTZ NOT NULL, UNIQUE(provider,provider_subject));
